  "summary": [
    "Bayesian posteriors place Frontier bankruptcy probability at about 8% within the May 1, 2026 window.",
    "Anchored to ULCC distress signals with a ~46% baseline, updated downward by sector stabilization cues.",
    "Downward updates come from Spirit's expected exit and Frontier's liquidity cushion; merger prospects add uncertainty but not clear uplift.",
    "Residual industry distress risk keeps tail risk, but no strong near-term bankruptcy forecast for Frontier."
  ],
  "confidence": "low",
  "narrative": "Starting from a distressed-ULCC anchor (~46%), Bayesian updates driven by Spirit's restructuring progress and Frontier's liquidity reduce Frontier’s bankruptcy probability to ~8% by May 1, 2026. The result reflects meaningful downside updates but acknowledges persistent sector tail risk and deal-uncertainty.",
  "justification": {
    "anchor": {
      "probability": 0.46,
      "basis": "Anchor from ULCC distress forecasts: ~46% bankruptcy probability over the next 24 months, used as starting point for Bayes updates."
    },
    "factor_updates": [
      {
        "factor": "Spirit Airlines Chapter 11 exit by summer 2026",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "A successful exit reduces sector distress spillovers and improves Frontier’s restructuring prospects, lowering bankruptcy probability within the window."
      },
      {
        "factor": "Frontier's liquidity cushion (near-term liquidity runway)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "A liquidity buffer around $889m (as of Mar-31-2025) and undrawn revolver dampen near-term distress signals."
      },
      {
        "factor": "Frontier not bankrupt / potential Spirit merger reduces risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Public signals show Frontier not bankrupt and potential merger with Spirit, reducing probability of bankruptcy."
      },
      {
        "factor": "ULCC sector distress signals",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Distress signals and peer Z-scores around 0.38-0.39 indicate higher tail risk for the sector."
      },
      {
        "factor": "Uncertainty around Spirit-Frontier merger outcomes",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Deal timing and viability inject uncertainty; not a clear affirmative uplift or downgrade."
      },
      {
        "factor": "No strong near-term Frontier bankruptcy forecast",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Across 2025–2026 reporting, credible forecasts do not imply imminent Frontier default; supports downward adjustment."
      }
    ],
    "synthesis_rationale": "The posterior of 8% results from combining a high-liability distress anchor with multiple, plausibly balanced updates; the positive updates (Spirit exit, Frontier liquidity, merger non-implosion) jointly reduce risk, while industry distress adds tail risk. Given potential correlations (e.g., sector distress correlated with Spirit outcomes) the net adjustment is substantial but not absolute, yielding a low-probability outcome with wide calibration."
  }
}

